import assert from "node:assert/strict";
import type {GeneratedBody} from "../../src/core/generators/definition";
import {legacy2018DevelopmentKnowledgeReview as review,legacy2018DevelopmentFixedFacts as fixed,legacy2018DevelopmentOtherFacts as facts} from "./legacy-2018-development-knowledge-review";
const options=(body:GeneratedBody)=>body.choices.map(choice=>{assert.equal(choice.length,1);assert(choice[0].type==="paragraph");return choice[0].text;});
const result=(body:GeneratedBody,truth:boolean[])=>{assert.equal(truth.length,4);assert.equal(truth.filter(Boolean).length,1);assert.equal(body.correctIndex,truth.indexOf(true));return truth;};
export function legacy2018DevelopmentKnowledgeOracle(source:string,body:GeneratedBody,values:number[]){
  const r=review.find(r=>`${r.collection}-${r.number}`===source);assert(r,source);assert.equal(body.answerParts,undefined);assert.equal(body.partAnswers,undefined);assert.equal(body.prompt.length,1);const prompt=body.prompt[0];assert(prompt.type==="paragraph");const actual=options(body);assert.equal(new Set(actual).size,4);assert.equal(actual.length,4);const number=r.number;
  if(fixed[number]){const f=fixed[number];assert.equal(prompt.text,f.stem);assert.equal(values.length,3);assert(values.every(n=>n===0||n===1));assert.equal(f.reasons.length,3);assert.equal(new Set([...f.roles,...f.changedRoles]).size,7);const wrong=[0,1,2,3].filter(i=>i!==f.correct),roles=[...f.roles];assert.equal(actual[f.correct],r.choices[f.correct]);wrong.forEach((i,j)=>{if(values[j]===0)assert.equal(actual[i],r.choices[i]);else{assert.equal(actual[i],f.changes[j]);for(const expression of f.changedClauses[j])assert.match(actual[i],expression);assert(!r.choices.includes(actual[i]));assert(!actual[i].includes("ではない"));roles[i]=f.changedRoles[j];}});for(const term of f.explanationTerms)assert(body.explanation.includes(term),term);if(number===57)assert(!/相対|他の三つと比べ|イが.*正答/.test(body.explanation));return result(body,roles.map(role=>role===f.roles[f.correct]));}
  assert.equal(values.length,1);const condition=values[0];assert(Number.isInteger(condition)&&condition>=0);
  if(number===48){assert(condition<2);assert.equal(prompt.text,facts.blackStems[condition]);assert.deepEqual(actual,r.choices);const roleByChoice=new Map(r.choices.map((s,i)=>[s,facts.blackRoles[i]]));for(const term of ["内部の実装から独立した機能仕様","同値クラスや境界値","流れ図など内部の構造","ランダムな標本","利用分布"])assert(body.explanation.includes(term));return result(body,actual.map(s=>roleByChoice.get(s)===facts.askedBlackRoles[condition]));}
  if(number===50){assert(condition<4);assert.equal(prompt.text,facts.xpPrefix+facts.xpDescriptions[condition]+"ものはどれか。");assert.deepEqual(actual,r.choices);const roleByChoice=new Map(r.choices.map((s,i)=>[s,facts.xpRoleByChoice[i]]));for(const term of ["Extreme Programming","二人で実装と確認の役割を交替","価値・優先順位と開発側の見積り","共通の書式や命名規則","Test-Driven Development"])assert(body.explanation.includes(term));return result(body,actual.map(s=>roleByChoice.get(s)===facts.xpAskedRoles[condition]));}
  const f=facts.one[number];assert(f);assert(condition<f.clauses.length);assert.equal(prompt.text,f.stem);const wrong=[0,1,2,3].filter(i=>i!==f.correct);for(const i of wrong)assert.equal(actual[i],r.choices[i]);if(condition===0)assert.equal(actual[f.correct],r.choices[f.correct]);assert.equal(actual[f.correct],f.claims[condition]);for(const expression of f.clauses[condition])assert.match(actual[f.correct],expression);for(const term of f.explanationTerms)assert(body.explanation.includes(term),term);const roles=actual.map((_,i)=>i===f.correct?f.roles[condition]:f.wrongRoles[wrong.indexOf(i)]);assert.equal(new Set(roles).size,4);

  if(number===59)assert(prompt.text.includes("最も避けるべき"));
  return result(body,roles.map(role=>f.roles.includes(role)));
}
